#include <iostream>
class Window {
 int low_=0,high_=0;
public:
 bool reset(int a,int b){if(a<0||b>100||a>b)return false;low_=a;high_=b;return true;}
 int width()const{return high_-low_;}
};
int main(){int a,b;if(!(std::cin>>a>>b)){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 Window w;bool ok=w.reset(a,b);std::cout<<(ok?"ok ":"rejected ")<<w.width()<<'\n';}

